package com.shazwan.idash;
import android.app.*;import android.os.*;import android.content.*;import android.net.wifi.WifiManager;import android.media.AudioManager;import android.view.*;import java.util.concurrent.atomic.AtomicReference;
/** Disposable emulator only. Restores Wi-Fi and media volume; never writes Airplane Mode. */
public class SystemControlsChecks extends Instrumentation {
 int count;LauncherActivity a;WifiManager wifi;AudioManager audio;boolean originalWifi,wifiCaptured;int originalVolume=-1;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);count++;}
 void ui(Runnable work){AtomicReference<Throwable> failure=new AtomicReference<>();runOnMainSync(()->{try{work.run();}catch(Throwable e){failure.set(e);}});waitForIdleSync();if(failure.get()!=null)throw new AssertionError(failure.get());}
 boolean waitWifi(boolean on)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){if(wifi.getWifiState()==(on?WifiManager.WIFI_STATE_ENABLED:WifiManager.WIFI_STATE_DISABLED))return true;Thread.sleep(150);}return false;}
 void back()throws Exception{Thread.sleep(1200);try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("am start -W -n com.shazwan.idash/.LauncherActivity");java.io.InputStream in=new java.io.FileInputStream(fd.getFileDescriptor())){byte[] buffer=new byte[1024];while(in.read(buffer)!=-1){}}long end=SystemClock.elapsedRealtime()+15000;while(!a.resumed&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);ui(()->check(a.resumed&&a.quickControls.observing,"explicit foreground return reattaches observers: resumed="+a.resumed+", observing="+a.quickControls.observing+", destroyed="+a.destroyed));}

 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
 a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();ui(a::controlCenter);QuickControls q=a.quickControls;
 check(QuickControls.wifiDirect(27)&&!QuickControls.wifiDirect(29),"Wi-Fi SDK policy");check(QuickControls.bluetoothDirect(27)&&QuickControls.bluetoothDirect(32)&&!QuickControls.bluetoothDirect(33),"Bluetooth SDK policy");
 ui(()->{check(q.observing,"observers attached while visible");q.resume();check(q.observing,"resume idempotent");check(q.wifi.getText().toString().contains(q.wifiState()),"display uses current Wi-Fi status");check(q.bluetooth.getText().toString().contains(q.bluetoothState()),"display uses actual Bluetooth or unavailable state");check(new ControlLayoutChecks().findText(q.dialog.getWindow().getDecorView(),"Airplane")==null,"Airplane UI removed; radio integration preserved");});
 wifi=(WifiManager)a.getApplicationContext().getSystemService(Context.WIFI_SERVICE);if(wifi!=null&&(wifi.getWifiState()==WifiManager.WIFI_STATE_ENABLED||wifi.getWifiState()==WifiManager.WIFI_STATE_DISABLED)){originalWifi=wifi.isWifiEnabled();wifiCaptured=true;ui(q::toggleWifi);check(waitWifi(!originalWifi),"actual Wi-Fi toggle through official API");ui(()->{q.refresh();check(q.wifi.getText().toString().contains(originalWifi?"Off":"On"),"Wi-Fi label follows changed radio state");});ui(q::toggleWifi);check(waitWifi(originalWifi),"Wi-Fi toggled back");}
 audio=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);originalVolume=audio.getStreamVolume(AudioManager.STREAM_MUSIC);final int low=Math.max(0,originalVolume-1),high=Math.min(audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC),originalVolume+1);final int before=q.volumeWrites;
 ui(()->{for(int i=0;i<50;i++)q.queueVolume(i%2==0?low:high);q.flushVolume();check(q.volumeWrites-before<=2,"burst volume requests coalesced");check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==high,"final volume reaches AudioManager");q.pause();check(!q.observing,"pause detaches observation");});int pausedWrites=q.volumeWrites;Thread.sleep(250);check(q.volumeWrites==pausedWrites,"no delayed volume write after pause");ui(q::resume);
 if("Unavailable".equals(q.bluetoothState())){ui(q::toggleBluetooth);long end=SystemClock.elapsedRealtime()+10000;while(a.resumed&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);check(!a.resumed,"missing Bluetooth adapter opens Settings fallback");back();}
 ui(()->{q.dialog.dismiss();});ui(()->check(!q.observing,"Back/dismiss releases observers and callbacks"));
 result.putString("stream","PASS: "+count+" system integration assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable failure){result.putString("stream","FAIL after "+count+": "+failure+"\n");}finally{try{if(wifi!=null&&wifiCaptured)wifi.setWifiEnabled(originalWifi);if(audio!=null&&originalVolume>=0)audio.setStreamVolume(AudioManager.STREAM_MUSIC,originalVolume,0);}catch(RuntimeException ignored){}if(a!=null)runOnMainSync(()->{if(a.quickControls!=null)a.quickControls.close();a.finish();});}finish(code,result);}
}
